(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((v||0)/100);
  const date=v=>v?String(v).slice(0,10).split('-').reverse().join('/'):'—';
  const types={income:'Recebimento',expense:'Pagamento',commission:'Comissão',transfer:'Transferência',opening:'Saldo inicial'};
  const statuses={open:'Em aberto',overdue:'Vencido',partial:'Parcial',paid:'Baixado',canceled:'Cancelado'};
  const paid=e=>e.legacyPaid?e.amountCents:e.payments.reduce((s,p)=>s+p.amountCents,0);
  const status=(e,today)=>e.canceled?'canceled':paid(e)>=e.amountCents?'paid':paid(e)?'partial':e.dueDate<today?'overdue':'open';
  let filters={},tab='entries',generation=0;
  window.TravelFinance={mount(root,{api,trips=[]}){
    let data,selected,busy=false,loadId=0,granatum={connected:false};
    const token=++generation,alive=()=>root.isConnected&&generation===token;
    const request=(path,method='GET',body)=>api.request('/finance'+path,{method,...(body===undefined?{}:{body})});
    const query=()=>new URLSearchParams(filters).toString();
    const options=(values,current,empty='Todos')=>`<option value="">${empty}</option>`+Object.entries(values).map(([v,n])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(n)}</option>`).join('');
    const cats=(kind,current,manual=false)=>Object.fromEntries(data.catalogs.filter(c=>c.kind===kind&&(!c.archived||c.id===current)&&!(manual&&c.source==='granatum')).map(c=>[c.id,c.name+(c.archived?' (arquivado)':'')]));
    const input=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
    const select=(name,label,values,value='',empty='Selecione')=>`<label>${label}<select name="${name}">${options(values,value,empty)}</select></label>`;
    const button=(action,label,id='',extra='')=>`<button type="button" data-fin-action="${action}" data-id="${esc(id)}" ${extra}>${label}</button>`;
    const name=id=>data.catalogs.find(c=>c.id===id)?.name||'Não definido';
    const notice=message=>{const el=root.querySelector('[data-fin-notice]');if(el){el.textContent=message;el.hidden=false;}};
    async function load(){const current=++loadId;try{const [next,connection]=await Promise.all([request('?'+query()),request('/granatum').catch(e=>({connected:false,error:e.message}))]);granatum=connection;if(!alive()||current!==loadId)return;data=next;filters={...next.filters};delete filters.today;delete filters.pageSize;draw();return true;}catch(e){if(alive())notice(e.message);return false;}}
    function draw(){root.innerHTML=`<header class="fin-heading"><div><span class="fin-eyebrow">GESTÃO DA AGÊNCIA</span><h1>Financeiro</h1><p>Compromissos, recebimentos e contas em um só lugar.</p></div><div>${button('export','Exportar CSV')}${button('new','+ Lançamento','','class="fin-primary"')}</div></header><p data-fin-notice role="alert" hidden></p><nav class="fin-tabs" aria-label="Visões financeiras">${[['entries','Lançamentos'],['flow','Fluxo de caixa'],['catalogs','Contas e cadastros']].map(([id,label])=>button('tab',label,id,`aria-current="${tab===id?'page':'false'}"`)).join('')}</nav>${granatumView()}${tab==='catalogs'?catalogView():filterView()+(tab==='flow'?flowView():entriesView())}<dialog id="finance-dialog"><header><h2 data-fin-title></h2>${button('close','Fechar')}</header><div data-fin-body></div><p data-fin-error role="alert" hidden></p></dialog>`;}
    function granatumView(){if(!granatum.connected)return granatum.error?`<p class="fin-warning">${esc(granatum.error)}</p>`:'';return `<section class="fin-panel fin-connection"><div><strong>Granatum conectado</strong><p class="fin-muted">${granatum.lastSync?'Última leitura: '+esc(new Date(granatum.lastSync).toLocaleString('pt-BR')):'Primeira importação em andamento.'}${granatum.stats?.entries!=null?' · '+granatum.stats.entries+' lançamentos':''}. Atualizações automáticas a cada hora. ${granatum.running?'Uma leitura está em andamento.':''}</p>${granatum.error?`<p role="alert" class="fin-warning">${esc(granatum.error)}</p>`:''}</div><div class="fin-actions">${granatum.stats?.from?button('granatum-range','Ver todo o período'):''}${data.manager?button('granatum-sync',granatum.running?'Continuar sincronização':'Sincronizar agora'):''}${data.manager&&granatum.error?button('granatum-restart','Reiniciar leitura'):''}</div></section>`;}
    function granatumDetails(e){const g=e.granatum||{};return `<section class="fin-warning"><strong>Origem: Granatum</strong>${e.type==='opening'?'<p>Saldo inicial da conta. Este valor não compõe receitas nem despesas.</p>':''}<p>Altere este lançamento no Granatum. A próxima sincronização atualizará o TravelPro.</p>${g.center?`<p>Centro de custo / lucro: ${esc(g.center)}</p>`:''}${g.paymentMethod?`<p>Forma de pagamento: ${esc(g.paymentMethod)}</p>`:''}${g.tags?.length?`<p>Tags: ${g.tags.map(esc).join(', ')}</p>`:''}${g.infinite?'<p>Recorrência contínua: as próximas ocorrências entrarão conforme forem disponibilizadas pelo Granatum.</p>':''}${g.attachments?.length?`<p>${g.attachments.length} anexo(s) disponível(is) no Granatum. Os arquivos permanecem na origem.</p>`:''}<small>Referência: ${esc(e.externalId)}</small></section>`;}
    function filterView(){return `<form data-fin-form="filter" class="fin-filters">${input('from','De',filters.from,'date','required')}${input('to','Até',filters.to,'date','required')}${select('basis','Período por',{dueDate:'Vencimento',competenceDate:'Competência'},filters.basis)}${select('type','Tipo',types,filters.type,'Todos')}${select('status','Situação',statuses,filters.status,'Ativos')}${select('accountId','Conta',cats('account'),filters.accountId,'Todas')}${select('categoryId','Categoria',cats('category'),filters.categoryId,'Todas')}${select('personId','Cliente / fornecedor',cats('person'),filters.personId,'Todos')}${select('source','Origem',{manual:'TravelPro',legacy:'Histórico anterior',granatum:'Granatum'},filters.source,'Todas')}${input('q','Buscar descrição ou documento',filters.q)}<button class="fin-primary">Aplicar filtros</button>${button('refresh','Atualizar')}</form>`;}
    function entriesView(){const s=data.summary;return `<div class="fin-summary">${[['A receber',s.receivable],['A pagar',s.payable],['Recebido',s.received],['Pago',s.paid]].map(([label,value])=>`<article><span>${label}</span><strong>${money(value)}</strong></article>`).join('')}</div><p class="fin-muted">Totais dos lançamentos filtrados. Em atraso: ${money(s.overdue)}.${s.legacyUndated?` ${s.legacyUndated} baixa(s) antiga(s) sem data; consulte o lançamento para regularizar.`:''}</p><div class="fin-table"><table><thead><tr><th>Descrição</th><th>Vencimento / competência</th><th>Conta / categoria</th><th>Situação</th><th>Valor / em aberto</th><th></th></tr></thead><tbody>${data.items.map(e=>`<tr><td><strong>${esc(e.title)}</strong><small>${types[e.type]}${e.installment?` · ${e.installment.number}/${e.installment.total}`:''} · ${e.source==='legacy'?'Histórico':e.source==='granatum'?'Granatum':'TravelPro'}</small>${e.personId?`<small>${esc(name(e.personId))}</small>`:''}</td><td>${date(e.dueDate)}<small>${date(e.competenceDate)}</small></td><td>${esc(name(e.accountId))}<small>${esc(e.type==='transfer'?name(e.toAccountId):name(e.categoryId))}</small></td><td><span class="fin-status fin-${status(e,data.today)}">${statuses[status(e,data.today)]}</span>${e.legacyPaid?'<small>Sem data da baixa</small>':''}</td><td><strong>${money(e.type==='opening'?e.openingSignedCents:e.amountCents)}</strong><small>${money(e.canceled?0:e.amountCents-paid(e))}</small></td><td>${button('detail','Abrir',e.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="fin-empty">Nenhum lançamento neste período. Ajuste os filtros ou crie um lançamento.</td></tr>'}</tbody></table></div><footer class="fin-pagination"><span>${data.total} lançamentos · página ${filters.page} de ${Math.max(1,Math.ceil(data.total/50))}</span><div>${button('previous','Anterior','',filters.page<=1?'disabled':'')}${button('next','Próxima','',filters.page*50>=data.total?'disabled':'')}</div></footer>`;}
    function flowView(){return `<section class="fin-panel"><h2>Realizado e previsto por mês</h2><p class="fin-muted">Realizado pela data de cada baixa; previsão pelo vencimento do saldo em aberto. Transferências e baixas antigas sem data não entram no realizado. Os demais filtros também se aplicam.</p><div class="fin-table"><table><thead><tr><th>Mês</th><th>Recebido</th><th>Pago</th><th>A receber</th><th>A pagar</th><th>Resultado realizado</th><th>Resultado previsto*</th></tr></thead><tbody>${data.monthly.map(m=>`<tr><td>${esc(m.month)}</td>${[m.received,m.paid,m.receivable,m.payable,m.received-m.paid,m.received-m.paid+m.receivable-m.payable].map(v=>`<td>${money(v)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="7">Sem movimentos no período.</td></tr>'}</tbody></table></div><p class="fin-muted">*Realizado mais valores em aberto. Não representa o saldo acumulado das contas.</p></section>`;}
    function catalogView(){return `<p class="fin-muted">Contas TravelPro: saldo inicial mais baixas. Contas Granatum: saldo informado na última leitura. Os saldos não dependem dos filtros.</p>${[['account','Contas'],['category','Categorias'],['person','Clientes e fornecedores']].map(([kind,title])=>`<section class="fin-panel"><div class="fin-heading"><h2>${title}</h2>${data.manager?button('catalog-new','+ Adicionar',kind):''}</div><div class="fin-catalogs">${data.catalogs.filter(c=>c.kind===kind).map(c=>`<article><div><strong>${esc(c.name)}</strong><small>${c.source==='granatum'&&kind==='account'?`Saldo informado pelo Granatum em ${date(c.balanceAt)}`:c.archived?'Arquivado':kind==='category'?({income:'Receitas',expense:'Despesas',both:'Receitas e despesas'}[c.type]):kind==='person'?({client:'Cliente',supplier:'Fornecedor',both:'Cliente e fornecedor'}[c.role]):`Saldo inicial: ${money(c.openingCents)} em ${date(c.openingDate)}`}</small>${kind==='account'?`<h3>${money(data.balances.find(b=>b.id===c.id)?.balanceCents)}</h3>`:''}</div>${data.manager&&c.source!=='granatum'?`<div>${button('catalog-edit','Editar',c.id)}${button('archive',c.archived?'Reativar':'Arquivar',c.id)}</div>`:''}</article>`).join('')||'<p class="fin-muted">Nenhum cadastro ainda.</p>'}</div></section>`).join('')}`;}
    function modal(title,html){const d=root.querySelector('dialog');d.querySelector('[data-fin-title]').textContent=title;d.querySelector('[data-fin-body]').innerHTML=html;d.querySelector('[data-fin-error]').hidden=true;if(!d.open)d.showModal();}
    const form=(kind,html)=>`<form data-fin-form="${kind}" class="fin-form">${html}<div class="fin-form-footer"><button class="fin-primary">Salvar</button>${button('close','Cancelar')}</div></form>`;
    function entryForm(e){selected=e||null;modal(e?'Editar lançamento':'Novo lançamento',form('entry',`<input type="hidden" name="requestId" value="${crypto.randomUUID()}">${input('title','Descrição',e?.title,'text','required maxlength="200"')}${select('type','Tipo',Object.fromEntries(Object.entries(types).filter(([k])=>k!=='opening')),e?.type||'income')}${input('amount',e?'Valor desta parcela (R$)':'Valor total (R$)',e?(e.amountCents/100).toFixed(2):'','number','min="0.01" step="0.01" required')}${!e?input('installments','Parcelas mensais',1,'number','min="1" max="120" required'):''}${input('dueDate','Vencimento / primeira parcela',e?.dueDate||data.today,'date','required')}${input('competenceDate','Competência / primeira parcela',e?.competenceDate||data.today,'date','required')}${select('accountId','Conta de origem',cats('account',e?.accountId,true),e?.accountId,'Sem conta')}${select('toAccountId','Conta destino (transferência)',cats('account',e?.toAccountId,true),e?.toAccountId,'Selecione para transferência')}${select('categoryId','Categoria',cats('category',e?.categoryId),e?.categoryId,'Sem categoria')}${select('personId','Cliente / fornecedor',cats('person',e?.personId),e?.personId,'Sem vínculo')}${select('tripId','Viagem',Object.fromEntries(trips.map(t=>[t.id,t.title])),e?.tripId,'Sem vínculo')}${input('document','Documento / referência',e?.document)}<label class="fin-wide">Observações<textarea name="notes" maxlength="5000">${esc(e?.notes)}</textarea></label>${!e?'<p class="fin-muted fin-wide">O valor total será dividido entre as parcelas. Vencimento e competência avançam um mês por parcela.</p>':''}`));}
    async function detail(id){const [e,h]=await Promise.all([request('/entries/'+encodeURIComponent(id)),request('/entries/'+encodeURIComponent(id)+'/history')]);if(!alive())return;selected=e;modal(e.title,`<div class="fin-detail"><p>${types[e.type]} · ${statuses[status(e,data.today)]}</p><h3>${money(e.type==='opening'?e.openingSignedCents:e.amountCents)}</h3><p>Em aberto: ${money(e.canceled?0:e.amountCents-paid(e))} · Vencimento: ${date(e.dueDate)} · Competência: ${date(e.competenceDate)}</p><p>Conta: ${esc(name(e.accountId))}${e.toAccountId?' → '+esc(name(e.toAccountId)):''}<br>Categoria: ${esc(name(e.categoryId))}<br>Cliente / fornecedor: ${esc(name(e.personId))}</p><p>${esc(e.document)}</p><p class="fin-notes">${esc(e.notes)}</p>${e.source==='granatum'?granatumDetails(e):''}<div class="fin-actions">${e.source!=='granatum'?`${!e.canceled?button('edit','Editar',id):''}${!e.canceled&&paid(e)<e.amountCents?button('pay','Registrar baixa',id,'class="fin-primary"'):''}${data.manager?button(e.canceled?'restore':'cancel',e.canceled?'Reabrir':'Cancelar lançamento',id):''}`:''}</div>${e.legacyPaid?`<p class="fin-warning">Baixa anterior sem data registrada. O valor foi preservado, mas não compõe o fluxo realizado nem o saldo das contas. Para regularizar, estorne esta baixa e registre a data correta.</p>${data.manager?button('reverse','Estornar baixa anterior','legacy'):''}`:''}<h3>Baixas registradas</h3>${e.payments.map(p=>`<div class="fin-payment"><span>${date(p.date)} · ${money(p.amountCents)}<small>${esc(p.note)}</small></span>${data.manager&&e.source!=='granatum'?button('reverse','Estornar',p.id):''}</div>`).join('')||'<p class="fin-muted">Nenhuma baixa com data registrada.</p>'}<h3>Histórico de alterações</h3><ol class="fin-history">${h.events.map(v=>`<li>${esc(new Date(v.created_at).toLocaleString('pt-BR'))} · ${esc(({granatum_sync:'Sincronizado do Granatum',granatum_deleted:'Excluído no Granatum',created:'Criado',create:'Criado',edited:'Editado',payments:'Baixa registrada',reverse:'Baixa estornada',cancel:'Cancelado',restore:'Reaberto',bootstrap:'Importado do histórico'})[v.action]||v.action)}${v.reason?' — '+esc(v.reason):''}</li>`).join('')}</ol></div>`);}
    function catalogForm(kind,c){selected=c||null;modal(c?'Editar cadastro':'Novo cadastro',form('catalog',`<input type="hidden" name="kind" value="${kind}">${input('name','Nome',c?.name,'text','required maxlength="150"')}${kind==='account'?input('openingAmount','Saldo inicial (R$)',((c?.openingCents||0)/100).toFixed(2),'number','step="0.01" required')+input('openingDate','Data do saldo inicial',c?.openingDate||data.today,'date',`required max="${data.today}"`)+'<p class="fin-muted fin-wide">Informe o saldo antes das movimentações dessa data. Alterar o saldo inicial recalcula o saldo atual.</p>':kind==='category'?select('type','Aplicação',{income:'Receitas',expense:'Despesas',both:'Ambos'},c?.type||'both'):select('role','Tipo',{client:'Cliente',supplier:'Fornecedor',both:'Ambos'},c?.role||'supplier')+input('email','E-mail',c?.email,'email')+input('document','CPF / CNPJ',c?.document)+input('phone','Telefone',c?.phone)}`));}
    root.addEventListener('click',async event=>{const b=event.target.closest('[data-fin-action]');if(!b||!root.contains(b)||busy)return;const action=b.dataset.finAction,id=b.dataset.id;try{
      if(action==='granatum-range'){filters={...filters,from:granatum.stats.from,to:granatum.stats.to,source:'granatum',page:1};tab='entries';return await load();}
      if(action==='granatum-sync'||action==='granatum-restart'){busy=true;b.disabled=true;b.textContent='Sincronizando...';const result=await request('/granatum/sync','POST',{restart:action==='granatum-restart'});await load();notice(result.running?'Sincronização em andamento. O servidor continuará automaticamente.':'Granatum atualizado.');return;}
      if(action==='close'){root.querySelector('dialog').close();return;}
      if(action==='tab'){tab=id;draw();return;}
      if(action==='refresh')return await load();
      if(action==='previous'||action==='next'){filters.page=Number(filters.page)+(action==='next'?1:-1);return await load();}
      if(action==='new')return entryForm();
      if(action==='detail')return await detail(id);
      if(action==='edit')return entryForm(selected);
      if(action==='pay')return modal('Registrar baixa',form('payment',input('amount','Valor da baixa (R$)',((selected.amountCents-paid(selected))/100).toFixed(2),'number','required min="0.01" step="0.01"')+input('date','Data do recebimento / pagamento',data.today,'date',`required max="${data.today}"`)+input('note','Observação')));
      if(['reverse','cancel','restore'].includes(action))return modal(action==='reverse'?'Estornar baixa':action==='cancel'?'Cancelar lançamento':'Reabrir lançamento',form('reason',`<input type="hidden" name="action" value="${action}"><input type="hidden" name="paymentId" value="${esc(id)}">${input('reason','Motivo','','text','required minlength="3" maxlength="500"')}`));
      if(action==='catalog-new')return catalogForm(id);
      if(action==='catalog-edit'){const c=data.catalogs.find(c=>c.id===id);return catalogForm(c.kind,c);}
      if(action==='archive'){const c=data.catalogs.find(c=>c.id===id);busy=true;await request('/catalogs/'+id,'PUT',{version:c.version,archive:!c.archived});return await load();}
      if(action==='export'){busy=true;b.disabled=true;const result=await request('/export?'+query());const url=URL.createObjectURL(new Blob([result.csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`travelpro-financeiro-${filters.from}-${filters.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    }catch(e){showError(e);}finally{busy=false;b.disabled=false;}});
    function showError(e){const d=root.querySelector('dialog');if(d?.open){const el=d.querySelector('[data-fin-error]');el.textContent=e.message;el.hidden=false;}else notice(e.message);}
    root.addEventListener('submit',async event=>{const f=event.target.closest('[data-fin-form]');if(!f)return;event.preventDefault();if(busy)return;const values=Object.fromEntries(new FormData(f)),kind=f.dataset.finForm;if(kind==='filter'){filters={...values,page:1};await load();return;}busy=true;const submit=f.querySelector('button');submit.disabled=true;try{
      if(kind==='entry')await request('/entries'+(selected?'/'+selected.id:''),selected?'PUT':'POST',{...values,...(selected?{version:selected.version}:{})});
      if(kind==='catalog')await request('/catalogs'+(selected?'/'+selected.id:''),selected?'PUT':'POST',{...values,...(selected?{version:selected.version}:{})});
      if(kind==='payment')await request('/entries/'+selected.id+'/payments','POST',{...values,version:selected.version});
      if(kind==='reason')await request('/entries/'+selected.id+'/'+values.action,'POST',{...values,version:selected.version});
      root.querySelector('dialog').close();const refreshed=await load();notice(refreshed?'Alteração salva.':'Alteração salva. Não foi possível atualizar a lista. Use Atualizar.');
    }catch(e){showError(e);}finally{busy=false;submit.disabled=false;}});
    load();
  }};
})();
